export function wikiI18n(locale: WikiLocale = 'zh') {
  return { locale, t: (key: string, values?: Record<string, string | number>) => (locale === 'en' ? en[key] ?? key : key)
    .replace(/\{(\w+)\}/g, (match, name: string) => String(values?.[name] ?? match)),
    errorMessage: (error: unknown) => { const message = error instanceof Error ? error.message : typeof error === 'string' ? error : '原始资料暂不可用'; return locale === 'en' ? en[message] ?? message : message; } };
}
const WikiI18nContext = createContext(wikiI18n());
export function WikiI18nProvider({ locale, children }: { locale: WikiLocale; children: ReactNode }) {
  return <WikiI18nContext.Provider value={wikiI18n(locale)}>{children}</WikiI18nContext.Provider>;
}
export const useWikiI18n = () => useContext(WikiI18nContext);
